// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
	if dstSlot == "" {
		return RecordInfo{}, &ConflictError{Reason: "目标存档槽名不能为空"}
	}
	if src == "" {
