	junk := filepath.Join(dir, recordsName, ".tmp-whatever")
	if err := os.WriteFile(junk, []byte("{not json"), 0o600); err != nil {
		t.Fatal(err)
	}
	_, _ = w.Apply(Commit{Time: 1})
	orphan := writeRawRecord(t, a, r0.ID, false, w.Snapshot())

