	// 损坏最新记录：截断文件。Latest 报损坏；恢复越过它找到可接受记录。
	if err := os.Truncate(recordPath(dir, r2), 40); err != nil {
		t.Fatal(err)
	}	if _, err := a.Latest("s", []string{"v1", "v2"}); err == nil {
		t.Fatal("损坏记录应报错")
	} else {
		var ce *CorruptError
		if !errors.As(err, &ce) {
			t.Fatalf("应返回 CorruptError，得到 %T", err)
