	}
	if rec2.ID != r1.ID {
		t.Fatalf("恢复结果错误: %s", rec2.ID)
	}

	// 连最后可接受的根也不可接受时 -> 不可恢复。
	_, err = a.RecoverLatest("s", []string{"v9"})
	if !errors.Is(err, ErrUnrecoverable) {
