// createSlotPointer 以 O_EXCL 创建槽指针文件：即便不经由锁的路径
// 也无法把两个首存混成同一个槽。
func (a *Archive) createSlotPointer(slot string, id RecordID) error {
	path := a.slotPath(slot)
	data, _ := json.MarshalIndent(slotPointer{Latest: id}, "", "  ")
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		if errors.Is(err, os.ErrExist) {
			return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
		}
		return err
	}
	clean := true
	defer func() {
		if clean {
			f.Close()
			os.Remove(path)
		}
	}()
	if _, err := f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	clean = false
	return syncDir(filepath.Join(a.dir, slotsName))
}

